async function* paginatedFetch(url) {
  let page = 1;
  while (true) {
    const res = await fetch(`${url}?page=${page}`);
    const data = await res.json();
    if (data.items.length === 0) break;
    for (const item of data.items) yield item;
    page++;
  }
}

